package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        if (owner.getRegistrationDate() == null) {
            owner.setRegistrationDate(LocalDate.now());
        }
        built.set(owner);
    }
}
===== DuplicateHouseholdException =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link CheckOwnerHouseholdUnique} when an owner create request shares both a last
 * name and an address (compared case-insensitively with collapsed whitespace) with an existing
 * owner, and the request did not opt in via {@code sharesHousehold}. Checked so it appears in the
 * {@code throws} clause and is routed to its escalation handler, which responds 409.
 */
public class DuplicateHouseholdException extends Exception {

    public DuplicateHouseholdException(String lastName, String address) {
        super("An owner with the same last name and address already exists: " + lastName + ", "
                + address);
    }
}
===== AssignCustomerCode =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>} where
 * {@code LAST3} is the upper-cased first three letters of {@code lastName} and
 * {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than the
 * current number of owners (e.g. {@code SMI-0007}).
 *
 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner}, so the count reflects
 * the owners that already exist and excludes the owner being created.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String lastName = owner.getLastName();
        int length = Math.min(3, lastName.length());
        String prefix = lastName.substring(0, length).toUpperCase();
        int sequence = ownerRepository.findAll().size() + 1;
        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
    }
}
