package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Household assignment for {@code POST /owners}. When the request opts in via
 * {@code sharesHousehold} true, the new owner joins the household of any existing owner that
 * shares its last name and address (compared case-insensitively with collapsed whitespace, the
 * same normalisation {@link CheckOwnerHouseholdUnique} uses). Both the joining owner and the
 * matched existing owners are assigned the same {@code householdId} — a stable shared identifier
 * derived from the normalised last name and address — so the household is discoverable from any
 * of its members. If a matched owner already carries a {@code householdId}, that value is reused
 * so the identifier stays stable as further members join.
 *
 * <p>Runs within the create transaction (after {@link BuildOwner}/{@link AssignCustomerCode},
 * before {@link SaveOwner}) so the back-filled identifiers on existing owners commit with the
 * new owner. Requests without {@code sharesHousehold} leave {@code householdId} null.
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = normalize(request.getAddress());
        List<Owner> matches = new ArrayList<>();
        String householdId = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(normalize(existing.getAddress()))) {
                matches.add(existing);
                if (householdId == null && existing.getHouseholdId() != null) {
                    householdId = existing.getHouseholdId();
                }
            }
        }
        if (householdId == null) {
            householdId = deriveHouseholdId(lastName, address);
        }
        owner.setHouseholdId(householdId);
        for (Owner existing : matches) {
            if (!householdId.equals(existing.getHouseholdId())) {
                existing.setHouseholdId(householdId);
                ownerRepository.save(existing);
            }
        }
    }

    private static String deriveHouseholdId(String lastName, String address) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest((lastName + "\n" + address).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

